def format_differences(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    for pair in rows:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise TypeError("each row must be a pair")
        if any(isinstance(value, bool) or not isinstance(value, int) for value in pair):
            raise TypeError("pair values must be integers")

    return [
        f"Entry {number}: {a} - {b} = {a - b}"
        for number, (a, b) in enumerate(rows, start=0)
    ]

